import org.junit.jupiter.api.io.TempDir;

/**
 * Census of the repository calls the Workbench makes (Summary, Types, Named Graphs, Explore): every call that binds a
 * statement field consults the in-memory direct adjacency without a structural fallback. Whole-store {@code size()} and
 * {@code getContextIDs()} are answered from LMDB's own counters, which are cheaper than adjacency. Prints one row per
 * call with adjacency hit/miss and fallback deltas.
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class LmdbWorkbenchAccessCensusTest {

	private static final String NS = "http://example.com/wbcensus/";
	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final int PEOPLE = 2000;

	@TempDir
	File dataDir;

	private SailRepository repository;
	private LmdbDirectAdjacencyStore direct;

	@BeforeAll
	void setUp() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30)
				.setValueOverlayEnabled(true);
		LmdbStore sail = new LmdbStore(dataDir, config);
		repository = new SailRepository(sail);
		repository.init();
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			for (int i = 0; i < PEOPLE; i++) {
				IRI person = iri("person" + i);
				conn.add(person, RDF.TYPE, iri("Person"));
				conn.add(person, iri("knows"), iri("person" + ((i + 1) % PEOPLE)));
				conn.add(person, iri("name"), F.createLiteral("person-" + i));
				conn.add(person, iri("worksAt"), iri("company" + (i % 40)), iri("g" + (i % 7)));
			}
			conn.commit();
		}
		direct = sail.getBackingStore().directAdjacencyStore();
		assertTrue(direct != null && direct.buildNowForTest(), "direct adjacency build must complete");
	}

	@AfterAll
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	void censusOfWorkbenchRepositoryCalls() {
		Map<String, ToLongFunction<RepositoryConnection>> calls = new LinkedHashMap<>();
		// size(g3) and size(default) are answered by the LMDB context catalog: one mdb_get of the exact
		// per-context statement count, which is at least as cheap as an adjacency lookup and needs no statement
		// scan, so neither consults the adjacency any more (LmdbDirectAdjacencyQueryTest pins that contract).
		List<String> answeredByLmdbCounters = List.of("size()", "size(g3)", "size(default)", "getContextIDs()");
		calls.put("size()", RepositoryConnection::size);
		calls.put("size(g3)", conn -> conn.size(iri("g3")));
		calls.put("size(default)", conn -> conn.size((Resource) null));
		calls.put("getContextIDs()", conn -> count(conn.getContextIDs()));
		calls.put("stmts(s,_,_)", conn -> count(conn.getStatements(iri("person42"), null, null, true)));
		calls.put("stmts(_,p,_)", conn -> count(conn.getStatements(null, iri("knows"), null, true)));
		calls.put("stmts(_,_,o)", conn -> count(conn.getStatements(null, null, iri("person42"), true)));
		calls.put("stmts(_,_,class)", conn -> count(conn.getStatements(null, null, iri("Person"), true)));
		calls.put("stmts(_,_,_,g3)", conn -> count(conn.getStatements(null, null, null, true, iri("g3"))));
		calls.put("has(_,_,o)", conn -> conn.hasStatement(null, null, iri("person42"), true) ? 1 : 0);
		calls.put("types distinct", conn -> count(conn
				.prepareTupleQuery("SELECT DISTINCT ?type WHERE { ?subj a ?type }")
				.evaluate()));
		calls.put("types counts", conn -> count(conn
				.prepareTupleQuery(
						"SELECT ?type (COUNT(DISTINCT ?s) AS ?instances) WHERE { ?s a ?type } GROUP BY ?type")
				.evaluate()));
		calls.put("graph counts", conn -> count(conn
				.prepareTupleQuery(
						"SELECT ?g (COUNT(*) AS ?n) WHERE { GRAPH ?g { ?s ?p ?o } } GROUP BY ?g")
				.evaluate()));

		System.out.printf("%n%-20s %8s %7s %7s %9s  %s%n", "call", "result", "adjHit", "adjMiss", "micros",
				"fallback deltas");
		for (Map.Entry<String, ToLongFunction<RepositoryConnection>> call : calls.entrySet()) {
			try (RepositoryConnection conn = repository.getConnection()) {
				call.getValue().applyAsLong(conn);
			}
			LmdbAdjacencyMetrics.Snapshot before = direct.snapshotMetrics();
			long started = System.nanoTime();
			long result;
			try (RepositoryConnection conn = repository.getConnection()) {
				result = call.getValue().applyAsLong(conn);
			}
			long micros = (System.nanoTime() - started) / 1000;
			LmdbAdjacencyMetrics.Snapshot after = direct.snapshotMetrics();
			System.out.printf("%-20s %8d %7d %7d %9d  %s%n", call.getKey(), result,
					after.lookupHits - before.lookupHits, after.exactMisses - before.exactMisses, micros,
					fallbackDeltas(before, after));
			assertEquals("-", fallbackDeltas(before, after), call.getKey() + " must not fall back structurally");
			if (!answeredByLmdbCounters.contains(call.getKey())) {
				assertTrue(after.lookupHits > before.lookupHits, call.getKey() + " must consult the adjacency");
			}
		}
	}

	private static long count(RepositoryResult<?> result) {
		long count = 0;
		try (result) {
			while (result.hasNext()) {
				result.next();
				count++;
			}
		}
		return count;
	}

	private static long count(TupleQueryResult result) {
		long count = 0;
		try (result) {
			while (result.hasNext()) {
				result.next();
				count++;
			}
		}
		return count;
	}

	private static String fallbackDeltas(LmdbAdjacencyMetrics.Snapshot before, LmdbAdjacencyMetrics.Snapshot after) {
		List<String> parts = new ArrayList<>();
		for (FallbackReason reason : FallbackReason.values()) {
			long delta = after.fallbacks(reason) - before.fallbacks(reason);
			if (delta != 0) {
				parts.add(reason + "=" + delta);
			}
		}
		return parts.isEmpty() ? "-" : String.join(" ", parts);
	}

	private static IRI iri(String local) {
		return F.createIRI(NS, local);
	}
}
